import pytest

@pytest.mark.parametrize("username, password", [
    ("valid_user", "valid_pass"),  # Valid credentials
    ("", ""),                     # Empty username and password
    ("valid_user", ""),           # Valid username, empty password
    ("", "valid_pass"),           # Empty username, valid password
    ("invalid_user", "invalid_pass")  # Invalid credentials
])
def test_user_login(api_client, username, password):
    """
    Test the /user/login endpoint.
    Covers various scenarios including valid, empty, and invalid credentials.
    """
    endpoint = "/user/login"
    params = {}
    if username:
        params["username"] = username
    if password:
        params["password"] = password

    # Make API request
    response = api_client.get(endpoint, params=params)

    # Validate response codes based on inputs
    if username == "valid_user" and password == "valid_pass":
        assert response.status_code == 200, f"Expected status 200, got {response.status_code}"
        assert "X-Rate-Limit" in response.headers, "Missing 'X-Rate-Limit' header in response"
        assert "X-Expires-After" in response.headers, "Missing 'X-Expires-After' header in response"
        response_content = response.json() if response.headers.get("Content-Type", "").startswith("application/json") else response.text
        assert isinstance(response_content, str), "Response content should be a string"
    elif not username or not password or username == "invalid_user":
        assert response.status_code == 400, f"Expected status 400, got {response.status_code}"
    else:
        assert response.status_code == 500 or response.status_code == 400, f"Unexpected status code: {response.status_code}"

def test_user_login_security(api_client, valid_api_key, invalid_api_key):
    """
    Test the /user/login endpoint with and without API keys (if applicable).
    """
    endpoint = "/user/login"
    headers = {"Authorization": f"Bearer {valid_api_key}"}
    params = {"username": "valid_user", "password": "valid_pass"}

    # Test with valid API key
    response = api_client.get(endpoint, headers=headers, params=params)
    assert response.status_code == 200, f"Expected status 200, got {response.status_code}"

    # Test with invalid API key
    headers["Authorization"] = f"Bearer {invalid_api_key}"
    response = api_client.get(endpoint, headers=headers, params=params)
    assert response.status_code in [401, 403], f"Expected status 401 or 403, got {response.status_code}"

    # Test with no API key
    response = api_client.get(endpoint, params=params)
    assert response.status_code in [401, 403], f"Expected status 401 or 403, got {response.status_code}"

